from .menu import Menu


class CommonPage(object):
    _menu = None

    def __init__(self, instance_dict):
        self._instance_dict = instance_dict
        if not self._menu:
            self._menu = Menu()

    def open_page_and_get_instance(self, view_page_name):
        """
        Get page instance and open it

        :param view_page_name: str
        :return: object, corresponding page instance
        """
        self._menu.open_page(self._instance_dict[view_page_name].MENU_ROUTE_LIST)
        return self._instance_dict[view_page_name]
